package com.nexushr.controller;

import com.nexushr.model.*;
import com.nexushr.repo.*;
import org.springframework.http.HttpStatus;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.security.core.Authentication;
import java.time.LocalDate;
import java.util.*;

@RestController @RequestMapping("/api/admin/users")
@org.springframework.security.access.prepost.PreAuthorize("hasRole('ADMIN')")
public class AdminUserController {
  private final UserRepository users; private final EmployeeRepository employees; private final DepartmentRepository departments; private final PasswordEncoder encoder; private final AdminAuditLogRepository audit;
  public AdminUserController(UserRepository u, EmployeeRepository e, DepartmentRepository d, PasswordEncoder p, AdminAuditLogRepository audit){users=u;employees=e;departments=d;encoder=p;this.audit=audit;}
  public record CreateUser(String name,String email,String password,String role,String designation,Long departmentId,Long managerId,Double salary){}
  public record UpdateUser(String role,Boolean active,String managerId){}
  private Map<String,Object> view(User u){Map<String,Object> m=new LinkedHashMap<>();m.put("id",u.id);m.put("name",u.name);m.put("email",u.email);m.put("role",u.role);m.put("active",u.active);m.put("employeeId",u.employee==null?null:u.employee.id);m.put("designation",u.employee==null?null:u.employee.designation);m.put("department",u.employee==null||u.employee.department==null?null:u.employee.department.name);m.put("managerId",u.employee==null||u.employee.manager==null?null:u.employee.manager.id);m.put("managerName",u.employee==null||u.employee.manager==null?null:u.employee.manager.name);return m;}
  @GetMapping @Transactional(readOnly=true) public List<Map<String,Object>> all(){return users.findAllWithEmployeeDetails().stream().map(this::view).toList();}
  @PostMapping @Transactional public Map<String,Object> create(@RequestBody CreateUser x){if(x.name()==null||x.name().isBlank()||x.email()==null||!x.email().contains("@")||x.password()==null||x.password().length()<8)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Name, valid email and password (8+ chars) are required");if(users.findByEmailIgnoreCase(x.email()).isPresent())throw new ResponseStatusException(HttpStatus.CONFLICT,"Email already exists");Role role;try{role=Role.valueOf(x.role());}catch(Exception ex){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid role");}Employee e=new Employee();e.name=x.name().trim();e.email=x.email().trim().toLowerCase();e.employeeCode="EMP"+UUID.randomUUID().toString().replace("-","").substring(0,10).toUpperCase();e.designation=x.designation();e.joiningDate=LocalDate.now();e.salary=x.salary()==null?0:x.salary();if(x.departmentId()!=null)e.department=departments.findById(x.departmentId()).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Department not found"));if(x.managerId()!=null){e.manager=employees.findById(x.managerId()).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Manager not found"));User managerUser=users.findByEmailIgnoreCase(e.manager.email).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Manager account not found"));if(managerUser.role!=Role.MANAGER||!managerUser.active)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Selected user is not an active Manager");}e=employees.save(e);User u=new User(e.name,e.email,encoder.encode(x.password()),role);u.employee=e;return view(users.save(u));}
  @PutMapping("/{id}/role") @Transactional public Map<String,Object> updateRole(Authentication auth,@PathVariable Long id,@RequestParam Role value){User u=users.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"User not found"));if(u.role==Role.MANAGER&&value!=Role.MANAGER&&u.employee!=null&&!employees.findByManagerId(u.employee.id).isEmpty())throw new ResponseStatusException(HttpStatus.CONFLICT,"Reassign this Manager’s team before changing their role");if(u.role==Role.ADMIN&&value!=Role.ADMIN&&users.findAll().stream().filter(a->a.active&&a.role==Role.ADMIN).count()<=1)throw new ResponseStatusException(HttpStatus.CONFLICT,"Cannot demote the last active Admin");Role old=u.role;u.role=value;users.save(u);audit.save(new AdminAuditLog(auth.getName(),"ROLE_CHANGED",id,old+" -> "+value));return view(u);}
  @PatchMapping("/{id}/active") @Transactional public Map<String,Object> active(Authentication auth,@PathVariable Long id,@RequestParam boolean value){User u=users.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"User not found"));if(u.role==Role.MANAGER&&!value&&u.employee!=null&&!employees.findByManagerId(u.employee.id).isEmpty())throw new ResponseStatusException(HttpStatus.CONFLICT,"Reassign this Manager’s team before deactivating the account");if(u.role==Role.ADMIN&&!value&&users.findAll().stream().filter(a->a.active&&a.role==Role.ADMIN).count()<=1)throw new ResponseStatusException(HttpStatus.CONFLICT,"Cannot deactivate the last active Admin");u.active=value;users.save(u);audit.save(new AdminAuditLog(auth.getName(),"ACCOUNT_STATUS_CHANGED",id,"active="+value));return view(u);}
  @PutMapping("/{id}/team") @Transactional public Map<String,Object> assign(Authentication auth,@PathVariable Long id,@RequestParam(required=false) Long managerId){User u=users.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"User not found"));if(u.employee==null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"User has no employee profile");if(u.role!=Role.EMPLOYEE)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Only Employee accounts can be assigned to a Manager");Long oldManagerId=u.employee.manager==null?null:u.employee.manager.id;if(managerId==null){u.employee.manager=null;}else{Employee manager=employees.findById(managerId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Manager employee not found"));User managerUser=users.findByEmailIgnoreCase(manager.email).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Manager account not found"));if(managerUser.role!=Role.MANAGER||!managerUser.active)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Selected user is not an active Manager");if(manager.id.equals(u.employee.id))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Manager cannot be assigned to themselves");u.employee.manager=manager;}employees.save(u.employee);audit.save(new AdminAuditLog(auth.getName(),"TEAM_ASSIGNMENT_CHANGED",id,"managerId="+oldManagerId+" -> "+managerId));return view(u);}
  @GetMapping("/audit") @Transactional(readOnly=true) public List<AdminAuditLog> audit(){return audit.findTop200ByOrderByCreatedAtDesc();}
  @PutMapping("/{id}/password") @Transactional public Map<String,Object> resetPassword(@PathVariable Long id,@RequestBody Map<String,String> body){User u=users.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"User not found"));String password=body.get("password");if(password==null||password.length()<8)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Password must be at least 8 characters");u.password=encoder.encode(password);u.tokenVersion++;users.save(u);return Map.of("message","Password reset successfully. Existing access tokens have been revoked.");}
}
